use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,fmt::Write,path::{Path,PathBuf},process::{Command,Stdio}};
const R:&str="/home/ubuntu/src/zopro-perf-work/solver-a-stream176";const O:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-06-solver-a-stream176";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn walk(p:&Path)->Vec<PathBuf>{let mut v=vec![];for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){v.extend(walk(&p))}else if p.is_file(){v.push(p);}}v.sort();v}
fn gzip(p:&Path,b:&[u8]){let tmp=p.with_extension("temporary");fs::write(&tmp,b).unwrap();assert!(Command::new("gzip").args(["-n","-c"]).arg(&tmp).stdout(Stdio::from(fs::File::create(p).unwrap())).status().unwrap().success());let d=Command::new("gzip").args(["-d","-c"]).arg(p).output().unwrap();assert!(d.status.success());assert_eq!(d.stdout,b);fs::remove_file(tmp).unwrap();}
fn main(){let review:Value=serde_json::from_slice(&fs::read(r("review.json")).unwrap()).unwrap();assert_eq!(review["passed"],true);assert_eq!(review["component_gate_passed"],false);let out=Path::new(O);assert!(!out.exists());fs::create_dir_all(out.join("artifacts")).unwrap();
 let mut source=BTreeMap::new();for p in walk(&r("source")){let b=fs::read(&p).unwrap();let hex=b.iter().map(|v|format!("{v:02x}")).collect::<String>();let restored=hex.as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect::<Vec<_>>();assert_eq!(restored,b);source.insert(p.strip_prefix(r("source")).unwrap().display().to_string(),json!({"hex":hex,"length":b.len(),"sha256":hash(&b)}));}assert_eq!(source.len(),179);gzip(&out.join("artifacts/source179.json.gz"),&serde_json::to_vec(&source).unwrap());
 let allowed=|p:&Path|matches!(p.extension().and_then(|s|s.to_str()),Some("rs"|"md"|"json"|"log"|"csv"));let mut files=vec![];for e in fs::read_dir(R).unwrap(){let p=e.unwrap().path();if p.is_file()&&allowed(&p){files.push(p);}}for d in["driver","native","preflight","capture","perf-fixed","stat"]{files.extend(walk(&r(d)).into_iter().filter(|p|allowed(p)));}
 let mut receipts=BTreeMap::new();for p in files{let b=fs::read(&p).unwrap();let text=String::from_utf8(b.clone()).unwrap();assert_eq!(text.as_bytes(),b);receipts.insert(p.display().to_string(),json!({"utf8":text,"length":b.len(),"sha256":hash(&b)}));}let count=receipts.len();gzip(&out.join("artifacts/receipts-and-helpers.json.gz"),&serde_json::to_vec(&receipts).unwrap());
 for w in[16,32]{for mode in["off","on"]{let name=format!("cycles-w{w}-{mode}.data");gzip(&out.join("artifacts").join(format!("{name}.gz")),&fs::read(r("perf").join(name)).unwrap());}}
 for f in["analysis.json","review.json","source-audit.json","identities.json","design.md","timing-protocol.md","stream.rs","ready.rs","trial.rs","driver.rs","setup.rs","campaign.rs","repair-perf-env.rs","analyze.rs","review.rs","publish.rs"]{fs::copy(r(f),out.join("artifacts").join(f)).unwrap();}
 fs::copy(r("report-draft.md"),out.join("README.md")).unwrap();let all=walk(out);let mut sums=String::new();for p in&all{writeln!(sums,"{}  {}",hash(&fs::read(p).unwrap()),p.strip_prefix(out).unwrap().display()).unwrap();}fs::write(out.join("SHA256SUMS"),sums).unwrap();println!("Published{}files/179source/{count}exactUTF8receipts/fourlosslessprofiles; allcompressed bytes roundtrip checked, no keys/witnesses/images/binaries/libraries.",all.len()+1);
}
